<?php
namespace App\Jobs;
use App\Events\OperationsUpdated;use App\Models\Backup;use App\Models\ActivityLog;use App\Services\Operations\BackupService;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Queue\Queueable;use Throwable;
class CreateBackupJob implements ShouldQueue{use Queueable;public int $tries=2;public int $timeout=1200;public function __construct(public int $backupId,public int $tenantId,public ?int $userId=null){$this->onQueue(config('infrastructure.queues.backups'));}public function handle(BackupService $service):void{$backup=Backup::where('tenant_id',$this->tenantId)->findOrFail($this->backupId);$backup->update(['status'=>'running','started_at'=>now(),'last_error'=>null]);event(new OperationsUpdated($this->tenantId,'backups','running',$backup->uuid));try{$service->create($backup);ActivityLog::create(['tenant_id'=>$this->tenantId,'user_id'=>$this->userId,'action'=>'backup.completed','description'=>$backup->name.' completed','subject_type'=>Backup::class,'subject_id'=>$backup->id]);event(new OperationsUpdated($this->tenantId,'backups','successful',$backup->uuid));}catch(Throwable $e){$backup->update(['status'=>'failed','completed_at'=>now(),'last_error'=>$e->getMessage()]);event(new OperationsUpdated($this->tenantId,'backups','failed',$backup->uuid));throw $e;}}}
